llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "The closest analogue, LCS1269, an indolocarbazole glycoside, is predicted to have human intestinal absorption consistent with bioavailability greater than 30%, supporting high F for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Roquinimex, which shares the N-methyl aryl amide motif, showed complete oral bioavailability in healthy volunteers, indicating that this amide motif does not impose a low-F liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tropisetron, an aromatic amide-containing drug, had absolute oral bioavailability of 52% in healthy volunteers, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Nintedanib, a large lipophilic kinase inhibitor, had absolute oral bioavailability of about 5%, providing a low-F counterexample; however, its low F is driven by ester hydrolysis, a liability absent in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Vinpocetine, a lipophilic alkaloid, had oral bioavailability around 7% due to poor solubility and first-pass metabolism; this is a lower-transferability counterexample because the query lacks the ester and has a different scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable evidence, especially the closest indolocarbazole glycoside analogues and the N-methyl aryl amide high-F drugs, supports F ≥ 20%; the low-F counterexamples are less transferable due to ester-specific liabilities and lower structural similarity.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability data for the query molecule.",
    "The closest indolocarbazole glycoside analogues are supported by predicted HIA rather than measured human F.",
    "Human absolute bioavailability for the staurosporine-type scaffold is not directly available in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

